float matrixSeed(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float matrixCharacter(vec2 local, float seed) {
  int glyph = int(floor(seed * 16.0));
  int bits = 0;
  // Compact terminal digits and angular code marks, four by six pixels.
  if (glyph == 0) bits = 6920598;
  else if (glyph == 1) bits = 7480932;
  else if (glyph == 2) bits = 15868007;
  else if (glyph == 3) bits = 7881863;
  else if (glyph == 4) bits = 8972441;
  else if (glyph == 5) bits = 7884575;
  else if (glyph == 6) bits = 6920118;
  else if (glyph == 7) bits = 2236975;
  else if (glyph == 8) bits = 6928022;
  else if (glyph == 9) bits = 7883158;
  else if (glyph == 10) bits = 11863279;
  else if (glyph == 11) bits = 2240239;
  else if (glyph == 12) bits = 4879970;
  else if (glyph == 13) bits = 3159631;
  else if (glyph == 14) bits = 10025887;
  else bits = 11756895;
  vec2 pixel = local * vec2(6.0, 8.0) - 1.0;
  vec2 cell = floor(pixel);
  int index = int(clamp(cell.y, 0.0, 5.0)) * 4 + int(clamp(cell.x, 0.0, 3.0));
  float bit = float((bits >> index) & 1);
  vec2 inset = abs(fract(pixel) - 0.5);
  vec2 aa = max(fwidth(pixel), vec2(0.04));
  vec2 stroke = 1.0 - smoothstep(vec2(0.49) - aa * 0.45, vec2(0.49) + aa * 0.45, inset);
  float inside = step(0.0, cell.x) * step(cell.x, 3.0) * step(0.0, cell.y) * step(cell.y, 5.0);
  return bit * stroke.x * stroke.y * inside;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 resolution = max(iResolution.xy, vec2(1.0));
  vec2 uv = fragCoord / resolution;
  float rows = uParam_density * min(1.0, resolution.y / 360.0);
  vec2 grid = vec2(rows * resolution.x / resolution.y * 1.32, rows);
  float column = floor(uv.x * grid.x);
  float seed = matrixSeed(vec2(column, 11.0));
  float velocity = mix(0.65, 1.28, seed);
  float phase = vrchPhase_speed();
  float travel = phase * rows * 0.24 * velocity;
  vec2 codePosition = vec2(uv.x * grid.x, uv.y * grid.y + travel);
  vec2 codeCell = floor(codePosition);
  vec2 local = fract(codePosition);
  float glyph = matrixCharacter(local, matrixSeed(codeCell + 7.0));

  float section = floor(uv.y * 7.0);
  float cut = matrixSeed(vec2(floor(column / 3.0), section + 19.0));
  float activeCut = smoothstep(0.58, 0.9, cut) * uParam_rupture;
  float displacedX = (cut - 0.5) * activeCut * 0.22;
  float displacedY = (seed - 0.5) * activeCut * 0.065;
  vec2 cellUv = vec2((codeCell.x + 0.5) / grid.x, (codeCell.y + 0.5 - travel) / grid.y) + vec2(displacedX, displacedY);
  cellUv = (cellUv - 0.5) * (1.0 - 0.3 * (uParam_presence - 0.45)) + 0.5;
  vec4 original = vrchSampleSource0(uv);
  vec3 cellColor = vrchSampleSource0(cellUv).rgb;
  float luminance = dot(cellColor, vec3(0.2126, 0.7152, 0.0722));
  float tone = pow(clamp(luminance, 0.0, 1.0), 0.68);
  float subject = smoothstep(0.025, 0.78, tone);

  float headDistance = fract(uv.y + phase * velocity * 0.21 + seed);
  float length = mix(0.12, 0.62, uParam_rain);
  float trail = 1.0 - smoothstep(0.0, length, headDistance);
  float head = 1.0 - smoothstep(0.008, 0.042, headDistance);
  float columns = smoothstep(0.23, 0.76, matrixSeed(vec2(column, 47.0)));
  float rainfall = trail * columns * uParam_rain;
  float scanY = 0.5 + 0.27 * sin(phase * 0.72);
  float scan = (1.0 - smoothstep(0.025, 0.095, abs(uv.y - scanY))) * uParam_scan;
  float resolved = mix(0.4, 1.3, uParam_presence);
  float codeLight = glyph * (subject * resolved + rainfall * (0.055 + 0.26 * subject));
  float glow = (0.006 + subject * 0.032) * (0.7 + uParam_presence);
  vec3 emerald = uParam_tint.rgb;
  vec3 headColor = mix(emerald, vec3(0.7, 1.0, 0.79), 0.55 + 0.4 * uParam_glow);
  vec3 portrait = emerald * (codeLight + glow);
  portrait += headColor * glyph * (head * columns * uParam_rain * 0.58 + scan * subject * 0.9) * (0.35 + 0.65 * uParam_glow);
  float glint = smoothstep(0.42, 0.76, subject) * smoothstep(0.42, 0.78, matrixSeed(codeCell + 31.0));
  portrait += vec3(0.48, 1.0, 0.66) * glyph * glint * uParam_glow * 0.9;
  portrait += emerald * glyph * subject * activeCut * 0.18;
  vec3 treated = clamp(portrait, 0.0, 1.0);
  fragColor = vec4(mix(original.rgb, treated, uParam_amount), original.a);
}
